@startuml

class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
  + score : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxLength : float
  + minLength : float
}

class HallOfFame {
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + startingArrangement : string[]
  + blocksAtStart : int
}

class GridPosition {
  + x : int
  + y : int
}

class Cell {
  + position : GridPosition
}

class GameSession {
  + currentLevel : int
  + currentScore : int
  + currentLives : int
  + isPaused : boolean
}

Admin "1" -- "*" Game : creates
Admin "0..1" -- "1" Game : manages
Player "0..*" -- "0..*" Game : plays
Player "1" -- "0..*" HallOfFame : competes in
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "*" Block
Game "1" *-- "0..1" GameSession
Level "1" *-- "*" Cell
Cell "0..1" -- "0..1" Block

@enduml

